INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱温离兖州，留葛从周守寨", "start_year": 895, "end_year": 895, "time_original": "895年朱温离兖州时；确月日未载", "dynasty": "唐", "description": "朱温离开兖州时，留葛从周领兵驻守，朱瑾闭城不再出战。", "phases": [], "location_name": "兗州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "390710a8-7fca-5816-a861-74d3726b9b8e"}, {"title": "葛从周诈称邀援，夜潜回寨设伏", "start_year": 895, "end_year": 895, "time_original": "895年末条；确月日未载", "dynasty": "唐", "description": "葛从周将还，扬言天平、河东援兵到、自己去西北截击，夜半偷偷返回旧寨。", "phases": [], "location_name": "兗州故寨", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "522c1d8f-19c9-599b-ab0b-dbb35ada2584"}, {"title": "朱瑾出攻旧寨，葛从周击败擒孙汉筠", "start_year": 895, "end_year": 895, "time_original": "895年末条；设伏夜后，确日未载", "dynasty": "唐", "description": "朱瑾以为葛从周精兵全出，出军攻寨；葛从周突击，杀千余人，擒都将孙汉筠后返回。", "phases": [], "location_name": "兗州故寨", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7d780018-4f28-5d20-8aed-deb9cb67c56c"}, {"title": "钱镠加兼侍中", "start_year": 895, "end_year": 895, "time_original": "895年末条；确月日未载", "dynasty": "唐", "description": "镇海节度使钱镠加兼侍中。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9388bd8f-88f7-545c-a275-31bc507f9eba"}, {"title": "彰义节度使张鐇去世", "start_year": 895, "end_year": 895, "time_original": "895年末条；确月日未载", "dynasty": "唐", "description": "彰义节度使张鐇去世。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "9a384957-16be-5480-91ad-6272d91fb355"}, {"title": "张琏权知彰义留后", "start_year": 895, "end_year": 895, "time_original": "895年末张鐇去世后条；确月日未载", "dynasty": "唐", "description": "朝廷以张鐇之子张琏暂任留后。", "phases": [], "location_name": "彰义", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6ddda6f4-0ae7-5217-b8af-4401566fb75a"}, {"title": "朱瑄朱瑾屡受攻，民财困而告急河东", "start_year": 895, "end_year": 895, "time_original": "895年末告急条；屡攻起讫未另载", "dynasty": "唐", "description": "朱瑄、朱瑾多次受朱温攻击，百姓失去耕种机会、财力困乏，二人向河东告急。", "phases": [], "location_name": "兗州、郓州、河东", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f5612b77-f4d8-506d-acc6-98be1c3ba8a9"}, {"title": "李克用遣史俨李承嗣数千骑借道魏援二朱", "start_year": 895, "end_year": 895, "time_original": "895年末告急以后；确月日未载", "dynasty": "唐", "description": "李克用派大将史俨、李承嗣率数千骑借道魏以救二朱。", "phases": [], "location_name": "魏、兗州、郓州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1303149f-cd5e-5d19-a2a6-5f75910a1d2b"}, {"title": "家晟与蒋玄晖有隙而惧祸", "start_year": null, "end_year": null, "time_original": "895年末条背景；嫌隙起始未载", "dynasty": "唐", "description": "安州防御使家晟与朱温亲吏蒋玄晖有嫌隙，担心遭祸。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "e4fc29dd-2864-5636-9768-43fee6dfd6ed"}, {"title": "家晟刘士政陈可璠三千兵袭桂州杀周元静", "start_year": 895, "end_year": 895, "time_original": "895年末条；系列行动确月日未载", "dynasty": "唐", "description": "家晟与指挥使刘士政、兵马监押陈可璠率三千兵袭桂州，杀经略使周元静，家晟取代其职。", "phases": [], "location_name": "桂州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2f00c1f0-c9ca-5f92-a316-6b78d59fd936"}, {"title": "家晟醉侮陈可璠，被其手刃", "start_year": 895, "end_year": 895, "time_original": "895年末条；袭桂州后，确日未载", "dynasty": "唐", "description": "家晟醉后侮辱陈可璠，陈可璠亲手杀死家晟。", "phases": [], "location_name": "桂州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ed122b58-9189-543a-ad78-46898a89b65a"}, {"title": "陈可璠推刘士政知军府，自为副使", "start_year": 895, "end_year": 895, "time_original": "895年末条；家晟被杀后，确日未载", "dynasty": "唐", "description": "陈可璠推刘士政掌军府，自己为副使。", "phases": [], "location_name": "桂州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "64232be8-a02a-5da8-b941-c8ef8eeff71d"}, {"title": "朝廷诏刘士政为桂管经略使", "start_year": 895, "end_year": 895, "time_original": "895年末条；推知军府后，确日未载", "dynasty": "唐", "description": "朝廷随即诏刘士政为桂管经略使。", "phases": [], "location_name": "桂管、朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "da629ffd-95ea-536f-bfb3-9604693f5047"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

