SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "朱温离开兖州时，留葛从周领兵驻守，朱瑾闭城不再出战。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p070·原文件第75行", "note": "原文：硃全忠之去兗州也，留葛从周将兵守之，硃瑾闭城不复出；核对说明：之去追接此前撤军，不认朱温本日又撤第二次；守之是城外营守，不作兖州城已属朱温。", "status": "draft", "id": "5ce76749-b869-5a77-a42e-32f4e0356390", "subject_id": "390710a8-7fca-5816-a861-74d3726b9b8e", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "895年朱温离兖州时；确月日未载", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p070·原文件第75行", "note": "原文：硃全忠之去兗州也，留葛从周将兵守之，硃瑾闭城不复出；核对说明：之去追接此前撤军，不认朱温本日又撤第二次；守之是城外营守，不作兖州城已属朱温。", "status": "draft", "id": "e9dd6b93-a25a-50b4-933c-642e11676454", "subject_id": "390710a8-7fca-5816-a861-74d3726b9b8e", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记朱温：留将者。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p070·原文件第75行", "note": "原文：硃全忠之去兗州也，留葛从周将兵守之，硃瑾闭城不复出，从周将还，乃扬言“天平、河东救兵至，引兵西北邀之，”夜半，潜归故寨。瑾以从周精兵悉出，果出兵攻寨。从周突出奋击，杀千馀人，擒其都将孙汉筠而还。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "8fdf1381-f3d5-52cf-8f68-caca93979d32", "subject_id": "0555e455-34d4-54ef-b93e-b0e6425018ab", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "朱温：留将者。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p070·原文件第75行", "note": "原文：硃全忠之去兗州也，留葛从周将兵守之，硃瑾闭城不复出；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "aed5e21d-3337-5a0a-9683-493b643cffac", "subject_id": "60ebf942-31d5-5324-82d9-7ff7dfa5ea63", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记葛从周：领兵留守者。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p070·原文件第75行", "note": "原文：硃全忠之去兗州也，留葛从周将